cd /home/daytona/workspace; python3 - <<'E'
s=open('controller.py').read()
s=s.replace('"""Right-hand punch on a hanging bag while standing on both feet."""','"""Strike a hanging bag: hand punch for chest-height bags, single-leg toe kick for low bags."""')
s=s.replace('T_END = 3.5\n','T_END = 3.5\nZ_KICK = 0.65    # bags hanging lower than this are kicked\n')
s=s.replace('        self.hand0 = p[self.side + "_hand"].copy()\n','''        self.hand0 = p[self.side + "_hand"].copy()
        self.kick = bool(bag[2] < Z_KICK)
        if self.kick:
            self.ks = self.side            # kicking foot on the bag's side
            self.sup = "left" if self.ks == "right" else "right"
            self.sup_foot = self.lf if self.sup == "left" else self.rf
            self.toe0 = p[self.ks + "_toe"].copy()
            tz = max(bag[2], 0.2)
            self.kwind = np.array([bag[0] - 0.30, bag[1], tz + 0.05])
            self.khit = np.array([bag[0] + 0.05, bag[1], tz])
            self.kcom = np.array([self.sup_foot[0] - 0.01, self.sup_foot[1] * 0.95])
''')
s=s.replace('''    def act(self, obs):
        t = obs["time"]
''','''    def _kick_act(self, obs):
        t = obs["time"]
        ta, tb, tc, td, te = 0.5, 1.7, 2.7, 2.7 + 0.2, 3.1   # shift, lift, (wind done), kick end, hold end
        tf, tg = te + 0.8, te + 0.8 + 1.2                    # retract end, com back
        sm = lambda s: s * s * (3 - 2 * s)
        if t < ta:
            sh = 0.0
        else:
            sh = sm(min(1.0, (t - ta) / (tb - ta)))
        if t > tf:
            sh = 1.0 - sm(min(1.0, (t - tf) / (tg - tf)))
        want = self.com_xy + sh * (self.kcom - self.com_xy)
        if t < tb:
            toe = self.toe0
        elif t < tc:
            toe = self.toe0 + sm((t - tb) / (tc - tb)) * (self.kwind - self.toe0)
        elif t < td:
            toe = self.kwind + (t - tc) / (td - tc) * (self.khit - self.kwind)
        elif t < te:
            toe = self.khit
        elif t < tf:
            toe = self.khit + sm((t - te) / (tf - te)) * (self.toe0 - self.khit)
        else:
            toe = self.toe0
        if t > tg + 0.3:
            self.done = True
        com_t = self.fb.update(want, obs["com"][:2])
        targets = {self.sup + "_foot": self.sup_foot, self.ks + "_toe": toe, "com": com_t}
        w = {self.ks + "_foot_level": 0.0}
        if t >= tf:
            targets = {"left_foot": self.lf, "right_foot": self.rf, "com": com_t}
            w = None
        self.q = self.wb.solve(self.q, targets, w)
        return list(self.q[7:])

    def act(self, obs):
        if self.kick:
            return self._kick_act(obs)
        t = obs["time"]
''')
open('controller.py','w').write(s)
